import React, { ReactElement } from 'react';
import { isElement } from 'react-is';

import { useTimeframeSelectorContext } from './hooks/useTimeframeSelectorContext.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';

export type TimeframeSelectorCustomTriggerProps = AriaLabelingProps &
  StylingProps &
  DataTestId & {
    /** Elements to be displayed in the CustomTrigger. */
    children: ReactElement;
  };

/**
 * Typeguard function that will check if a React.Node is a TimeframeSelector.CustomTrigger
 * @internal
 */
export function _isTimeframeSelectorCustomTriggerElement(
  child: React.ReactNode,
): child is React.ReactElement<TimeframeSelectorCustomTriggerProps> {
  return isElement(child) && child.type === CustomTrigger;
}

/**
 * A trigger component to customize a timeframe selector's trigger.
 * It applies all necessary props on the first and closest child,
 * which, therefore, should be an interactive element.
 */
export const CustomTrigger = (props: TimeframeSelectorCustomTriggerProps) => {
  const { children, ...remainingProps } = props;
  const { triggerProps } = useTimeframeSelectorContext();

  return React.cloneElement(children, {
    ..._mergeProps(triggerProps, remainingProps, children.props),
  });
};

CustomTrigger['displayName'] = 'TimeframeSelector.CustomTrigger';
